import{_ as e,o as d,c as o,a4 as r}from"./chunks/framework.BaMAT_0D.js";const u=JSON.parse('{"title":"Test results","description":"","frontmatter":{},"headers":[],"relativePath":"Lab/Advanced_Data_Structure/Project1_SkipList/test_results.md","filePath":"Lab/Advanced_Data_Structure/Project1_SkipList/test_results.md","lastUpdated":1793365822000}'),i={name:"Lab/Advanced_Data_Structure/Project1_SkipList/test_results.md"};function s(a,t,c,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="test-results" tabindex="-1">Test results <a class="header-anchor" href="#test-results" aria-label="Permalink to &quot;Test results&quot;">​</a></h1><p>Verified on Windows with GCC; regenerate with <code>python -X utf8 -B tests/verify_real.py</code> from <code>project1/</code>.</p><h2 id="compilation-and-automatic-regression-tests" tabindex="-1">Compilation and automatic regression tests <a class="header-anchor" href="#compilation-and-automatic-regression-tests" aria-label="Permalink to &quot;Compilation and automatic regression tests&quot;">​</a></h2><ul><li><code>gcc project_1.c stemmer.c -o project_1</code>: exit 0, no diagnostics.</li><li><code>python -X utf8 -B tests/run_tests.py</code>: 24 tests passed.</li><li><code>python -X utf8 -B tests/test_preparation.py</code>: 3 tests passed.</li><li>The original stop-word, duplicate-score and phrase bugs were reproduced before fixing.</li><li>Exact positions: connect = <code>1:4[8,9,10,11] 2:1[9] 3:1[7]</code>; comet = <code>3:2[8,9]</code>.</li><li>13,050-position posting, index line &gt;65,536 bytes: frequency 13,050 and <code>echo echo</code> count 13,049 after reload.</li><li>All four query types have identical output after Build and a fresh Search process.</li><li>Word/minimum-count/percentage queries work with no <code>data/</code> directory; missing phrase originals are explicitly reported.</li><li>Invalid percentage/k, punctuation, duplicate stems, empty input, EOF, oversized tokens/phrases and malformed index records covered.</li></ul><h2 id="cleaned-corpus" tabindex="-1">Cleaned corpus <a class="header-anchor" href="#cleaned-corpus" aria-label="Permalink to &quot;Cleaned corpus&quot;">​</a></h2><p>37 plays; 905,286 raw tokens; 22,926 distinct raw tokens; 31 stop words; 14,375 index terms; 610,307 indexed positions; 102,344 term/document postings.</p><p>Index size: 4,105,525 bytes; maximum line: 30,586 bytes. No stop-word entries remain. The shared corpus is in <code>program/data/</code>; navigation text is absent.</p><p>Stage directions and character labels are included. Poetry is outside this dataset.</p><h2 id="real-queries" tabindex="-1">Real queries <a class="header-anchor" href="#real-queries" aria-label="Permalink to &quot;Real queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Query</th><th>Parameter</th><th style="text-align:right;">Documents</th><th>Matches / note</th></tr></thead><tbody><tr><td>Word</td><td><code>king!</code></td><td>—</td><td style="text-align:right;">36</td><td>3236 total occurrences</td></tr><tr><td>Word</td><td><code>being</code></td><td>—</td><td style="text-align:right;">0</td><td>No matches</td></tr><tr><td>Word</td><td><code>homepage</code></td><td>—</td><td style="text-align:right;">0</td><td>No matches</td></tr><tr><td>Minimum Match Count</td><td><code>king, queen powerful</code></td><td>3</td><td style="text-align:right;">29</td><td>3 distinct stems required</td></tr><tr><td>Minimum Match Count</td><td><code>king king queen</code></td><td>3</td><td style="text-align:right;">0</td><td>k=3 exceeds 2 effective terms; explicitly rejected</td></tr><tr><td>Phrase</td><td><code>love king</code></td><td>—</td><td style="text-align:right;">3</td><td>2henryiv.txt: 1; henryv.txt: 1; richardii.txt: 1</td></tr><tr><td>Phrase</td><td><code>love the king</code></td><td>—</td><td style="text-align:right;">3</td><td>allswell.txt: 1; pericles.txt: 1; winters_tale.txt: 1</td></tr><tr><td>Phrase</td><td><code>to be or not to be</code></td><td>—</td><td style="text-align:right;">1</td><td>hamlet.txt: 1</td></tr><tr><td>Phrase</td><td><code>of the king</code></td><td>—</td><td style="text-align:right;">18</td><td>60 total occurrences</td></tr></tbody></table><h2 id="query-thresholding" tabindex="-1">Query Thresholding <a class="header-anchor" href="#query-thresholding" aria-label="Permalink to &quot;Query Thresholding&quot;">​</a></h2><p>Sort by increasing df; break df ties by stem spelling. Keep <code>ceil(n*p/100)</code> distinct stems and use AND. An absent indexed term has df=0 and is retained.</p><table tabindex="0"><thead><tr><th>Query</th><th style="text-align:right;">Percent</th><th>Selected terms</th><th style="text-align:right;">Documents</th></tr></thead><tbody><tr><td><code>fairy witch ghost sword night</code></td><td style="text-align:right;">20%</td><td><code>fairi</code></td><td style="text-align:right;">13</td></tr><tr><td><code>fairy witch ghost sword night</code></td><td style="text-align:right;">40%</td><td><code>fairi witch</code></td><td style="text-align:right;">10</td></tr><tr><td><code>fairy witch ghost sword night</code></td><td style="text-align:right;">60%</td><td><code>fairi witch ghost</code></td><td style="text-align:right;">7</td></tr><tr><td><code>fairy witch ghost sword night</code></td><td style="text-align:right;">80%</td><td><code>fairi witch ghost sword</code></td><td style="text-align:right;">7</td></tr><tr><td><code>fairy witch ghost sword night</code></td><td style="text-align:right;">100%</td><td><code>fairi witch ghost sword night</code></td><td style="text-align:right;">7</td></tr><tr><td><code>romeo tomb poison king love</code></td><td style="text-align:right;">20%</td><td><code>romeo</code></td><td style="text-align:right;">1</td></tr><tr><td><code>romeo tomb poison king love</code></td><td style="text-align:right;">40%</td><td><code>romeo tomb</code></td><td style="text-align:right;">1</td></tr><tr><td><code>romeo tomb poison king love</code></td><td style="text-align:right;">60%</td><td><code>romeo tomb poison</code></td><td style="text-align:right;">1</td></tr><tr><td><code>romeo tomb poison king love</code></td><td style="text-align:right;">80%</td><td><code>romeo tomb poison king</code></td><td style="text-align:right;">1</td></tr><tr><td><code>romeo tomb poison king love</code></td><td style="text-align:right;">100%</td><td><code>romeo tomb poison king love</code></td><td style="text-align:right;">1</td></tr></tbody></table><p>Measured df: <code>fairy</code>=13, <code>witch</code>=18, <code>ghost</code>=19, <code>sword</code>=35, <code>night</code>=37, <code>romeo</code>=1, <code>tomb</code>=21, <code>poison</code>=31, <code>king</code>=36, <code>love</code>=37.</p><p>The first query reaches the full-term result at 60%; the second at 20%. This compares result sets, not measured precision/recall: no relevance labels are available.</p><h2 id="evidence" tabindex="-1">Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;Evidence&quot;">​</a></h2><ul><li><a href="tests/results/real_build.txt">Build transcript</a> and <a href="tests/results/real_search.txt">fresh Search transcript</a>: 19 real query cases, identical query output.</li><li><a href="tests/results/metrics.json">Measured metrics</a>. Phrase results independently checked against raw ASCII token sequences in all 37 plays.</li><li><a href="tests/results/compilation.txt">Compilation checks</a>, <a href="tests/results/regression.txt">C regression transcript</a>, <a href="tests/results/preparation.txt">preparation transcript</a>: generated by <code>tests/run_all.py</code>.</li><li><code>stemmer.c</code> SHA-256 unchanged: <code>17a3b96a17f535556682eb1d8f695cb4f60635be92d764575329fbe89d5664ec</code>.</li></ul>',17)])])}const p=e(i,[["render",s]]);export{u as __pageData,p as default};
